css:
.fx-prl{width:min(480px,100%);text-align:center}
.fx-prl .seg{display:inline-flex;border:1px solid var(--border);border-radius:99px;padding:.25em;margin-bottom:1.4em}
.fx-prl .seg button{border:0;background:none;color:var(--text);padding:.55em 1.2em;border-radius:99px;font:700 .9em var(--font-body);cursor:pointer;transition:all calc(.25s/var(--speed))}
.fx-prl .seg button[aria-pressed=true]{background:var(--primary);color:var(--on-primary)}
.fx-prl .amt{display:flex;justify-content:center;align-items:flex-end;font:700 clamp(3em,10vw,5em)/1 var(--font-heading);color:var(--primary);height:1.05em;overflow:hidden}
.fx-prl .amt small{font:600 .3em var(--font-body);margin:0 .4em .3em 0;opacity:.6}
.fx-prl .col{display:inline-block;height:1.05em;overflow:hidden}
.fx-prl .col>span{display:flex;flex-direction:column;transition:transform calc(.7s/var(--speed)) cubic-bezier(.2,.9,.25,1)}
.fx-prl .col>span>i{font-style:normal;height:1.05em;line-height:1.05em;text-align:center}
.fx-prl .sep{display:inline-block;line-height:1.05em}
.fx-prl p{margin-top:.8em;opacity:.7;font-size:.92em}
@media(prefers-reduced-motion:reduce){.fx-prl .col>span{transition:none}}

js:
(function(){var r=document.querySelector('.fx-prl'),bs=r.querySelectorAll('.seg button'),a=r.querySelector('#fx-prl-a'),t=r.querySelector('#fx-prl-t'),cols=[];
function build(n){a.innerHTML='';cols=[];var s=n.toLocaleString('en-US');for(var i=0;i<s.length;i++){if(s[i]===','){var c=document.createElement('span');c.className='sep';c.textContent=',';a.appendChild(c);cols.push(null);continue}
var col=document.createElement('span');col.className='col';var in_=document.createElement('span');for(var d=0;d<10;d++){var e=document.createElement('i');e.textContent=d;in_.appendChild(e)}col.appendChild(in_);a.appendChild(col);cols.push(in_)}}
function set(n){var s=n.toLocaleString('en-US');if(cols.length!==s.length)build(n);for(var i=0;i<s.length;i++){if(cols[i])cols[i].style.transform='translateY(-'+(+s[i]*10)+'%)'}}
bs.forEach(function(b){b.onclick=function(){bs.forEach(function(x){x.setAttribute('aria-pressed',x===b)});var n=+b.dataset.v;set(n);t.textContent='RM '+n.toLocaleString('en-US')+' — '+b.textContent+' package'}});
build(12800);requestAnimationFrame(function(){set(12800)})})();
